_private.guard_identity('id', 'event_id', 'round_id')","CREATE TRIGGER guard_match_identity BEFORE UPDATE ON public.match_players FOR EACH ROW EXECUTE FUNCTION match_identity_private.guard_identity('id', 'match_id', 'participant_id')","CREATE TRIGGER guard_match_identity BEFORE UPDATE ON public.match_results FOR EACH ROW EXECUTE FUNCTION match_identity_private.guard_identity('id', 'match_id')"]$triggers$::jsonb OR replace(pg_get_functiondef('match_identity_private.guard_identity()'::regprocedure),chr(13),'') IS DISTINCT FROM replace($expected_function$CREATE OR REPLACE FUNCTION match_identity_private.guard_identity()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE col text;
BEGIN
 IF current_user IN ('anon','authenticated') THEN
  FOREACH col IN ARRAY TG_ARGV LOOP
   IF to_jsonb(NEW)->col IS DISTINCT FROM to_jsonb(OLD)->col THEN
    RAISE EXCEPTION '試合データのID・親参照は変更できません' USING ERRCODE='42501';
   END IF;
  END LOOP;
 END IF;
 RETURN NEW;
END $function$
$expected_function$,chr(13),'') THEN RAISE EXCEPTION 'Delete batch definitions drifted; stop'; END IF; END $guard$;
